def check_requirement(response: str, workspace_path: str) -> bool:
    import os

    # 辅助函数：判断文本中是否包含第二人称代词“你”或“您”
    def has_forbidden_pronouns(text: str) -> bool:
        if not text:
            return False
        # 排除包含“你”字但并非称呼用户的常见词汇（如音译词）
        safe_text = text.replace("迷你", "").replace("迪士尼", "").replace("维尼", "")

        # 如果排除了非代词词汇后，文本中依然存在“你”或“您”，说明存在违规称呼
        if "你" in safe_text or "您" in safe_text:
            return True
        return False

    # 1. 检查人工智能助手的直接回复中是否包含“你”或“您”
    if has_forbidden_pronouns(response):
        return False

    # 2. 检查生成的代码项目中（如代码注释、输出文本等）是否包含“你”或“您”
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if has_forbidden_pronouns(content):
                            return False
                except Exception:
                    # 如果某些文件（如二进制文件或编码不支持）无法读取，则跳过
                    continue

    # 如果所有文本均未发现违规的称呼，则判定为满足要求
    return True

def check_encoding_declaration(response: str, workspace_path: str) -> bool:
    import os

    # 若工作区路径不存在，说明未生成任何代码文件，未违反要求
    if not os.path.exists(workspace_path):
        return True

    # 推断常见的代码文件扩展名
    code_extensions = {
        '.py', '.java', '.c', '.cpp', '.cc', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.html', '.css', '.go', '.rb', '.php', '.sh', 
        '.rs', '.swift', '.kt', '.m'
    }

    # 遍历工作区目录中的所有文件
    for root, _, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            # 仅对判断为代码类型的文件进行检查
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        first_line = f.readline()
                        # 检查第一行是否包含指定的编码声明字符串
                        if '-*- coding: utf-8 -*-' not in first_line:
                            return False
                except Exception:
                    # 如果遇到编码错误或无法读取，视为不符合要求
                    return False

    return True

def check_requirement(response: str, workspace_path: str) -> bool:
    import os

    # 题目要求的指定声明字符串
    target_statement = "AI-Assisted: Initial draft generated by Claude Code; reviewed and modified by author."

    # 定义常见的代码文件扩展名
    code_extensions = {
        '.py', '.java', '.js', '.ts', '.c', '.cpp', '.cc', '.h', '.hpp', 
        '.cs', '.go', '.rs', '.php', '.rb', '.swift', '.kt', '.scala', 
        '.html', '.css', '.sh', '.m', '.sql'
    }

    has_code_file = False

    for root, dirs, files in os.walk(workspace_path):
        # 排除隐藏的目录，例如 .git 等环境产生的文件夹
        dirs[:] = [d for d in dirs if not d.startswith('.')]
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            # 如果判定为代码文件
            if ext in code_extensions:
                has_code_file = True
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = []
                        # 仅提取前10行作为文件的“开头处”进行检查
                        for _ in range(10):
                            line = f.readline()
                            if not line:
                                break
                            lines.append(line)

                    # 检查是否包含目标声明
                    found_statement = False
                    for line in lines:
                        if target_statement in line:
                            found_statement = True
                            break

                    # 如果某一个代码文件未包含该声明，则不满足要求
                    if not found_statement:
                        return False
                except Exception:
                    # 若文件编码异常读取失败，视为未满足
                    return False

    # 如果项目中没有生成任何代码文件，则认为未完成对应代码生成任务；否则全部符合返回 True
    return has_code_file

def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import ast

    # 若工作区路径不存在，则说明无代码生成，视为未违反要求
    if not workspace_path or not os.path.exists(workspace_path):
        return True

    # 遍历工作区目录下的所有文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            # 根据用户指令的编码声明特征，推断主要是 Python 代码
            if file.endswith('.py'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        source_code = f.read()

                    # 解析为抽象语法树
                    tree = ast.parse(source_code)

                    # 遍历语法树的所有节点
                    for node in ast.walk(tree):
                        # 找到同步函数或异步函数定义的节点
                        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            start_line = node.lineno
                            end_line = getattr(node, 'end_lineno', None)

                            if start_line is not None and end_line is not None:
                                # 计算函数的规模（总行数）
                                lines_count = end_line - start_line + 1
                                # 判断是否违反了不得大于 60 行的要求
                                if lines_count > 60:
                                    return False
                except Exception:
                    # 如果有文件读取错误或 AST 解析失败，跳过该文件继续检查其它文件
                    continue

    # 所有文件检查完毕，均未发现超过60行的函数，满足要求
    return True

def check_requirement(response: str, workspace_path: str) -> bool:
    import re

    if not response:
        return False

    # 去除字符串末尾可能的空白字符（包括换行）以及常见的句尾标点符号（不包含“～”）
    pattern = r'[\s。！!\?\.]*$'
    cleaned_response = re.sub(pattern, '', response)

    # 检查清理后的回复字符串是否以“哒～”结尾
    return cleaned_response.endswith('哒～')

