def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    if not os.path.exists(workspace_path):
        return False

    def check_py_functions(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                lines = f.readlines()
        except Exception:
            return True

        for i, line in enumerate(lines):
            if re.match(r'^\s*(?:async\s+)?def\s+\w+', line):
                indent = len(line) - len(line.lstrip())
                start = i
                end = i
                for j in range(i + 1, len(lines)):
                    strip_line = lines[j].strip()
                    # 跳过空行和纯注释行
                    if not strip_line or strip_line.startswith('#'):
                        end = j
                        continue
                    current_indent = len(lines[j]) - len(lines[j].lstrip())
                    if current_indent <= indent:
                        break
                    end = j

                if end - start + 1 > 60:
                    return False
        return True

    def check_js_html_functions(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                file_content = f.read()
        except Exception:
            return True

        # 保留换行符，以防行号计算错位
        def replacer_multiline(match):
            return '\n' * match.group(0).count('\n')

        # 清除多行注释
        content = re.sub(r'/\*[\s\S]*?\*/', replacer_multiline, file_content)
        # 清除单行注释（不匹配换行，原行号保留）
        content = re.sub(r'//.*', '', content)
        # 清除字符串（不支持换行的普通字符串和支持换行的模板字符串分别处理）
        content = re.sub(r'"(?:\\.|[^"\\\n])*"', '', content)
        content = re.sub(r"'(?:\\.|[^'\\\n])*'", '', content)
        content = re.sub(r'`(?:\\.|[^`\\])*`', replacer_multiline, content)

        blocks = []
        stack = []

        # 精确记录每一个左右花括号对的跨度
        for i, char in enumerate(content):
            if char == '{':
                stack.append(i)
            elif char == '}':
                if stack:
                    start_idx = stack.pop()
                    blocks.append((start_idx, i))

        for start_idx, end_idx in blocks:
            # 计算当前大括号块的总行数
            start_line = content[:start_idx].count('\n')
            end_line = content[:end_idx].count('\n')

            # 若检测到规模大于 60 行的代码块
            if end_line - start_line + 1 > 60:
                # 倒推寻找最近一个分隔符，提取其声明头部
                prev_brace = content.rfind('}', 0, start_idx)
                prev_semi = content.rfind(';', 0, start_idx)
                prev_boundary = max(prev_brace, prev_semi, 0)

                header = content[prev_boundary:start_idx].strip()

                # 定义 3 种常见的函数匹配特征（要求刚好在左花括号前结束）
                # 1. 传统函数声明 function foo()
                func_pattern = r'\bfunction(?:\s+\w+)?\s*\([^{}]*\)\s*$'
                # 2. 箭头函数 () =>
                arrow_pattern = r'(?:\([^{}]*\)|\b\w+)\s*=>\s*$'
                # 3. 常见对象的简写方法定义 foo()
                method_pattern = r'\b(?!(?:if|for|while|switch|catch|with)\b)\w+\s*\([^{}]*\)\s*$'

                # 如果这个超大代码块是由于函数结构引发的，则违规
                if re.search(func_pattern, header) or \
                   re.search(arrow_pattern, header) or \
                   re.search(method_pattern, header):
                    return False

        return True

    # 遍历当前工作区所有的代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            # 解析前端常用的带有花括号语法的文件
            if file.endswith(('.js', '.ts', '.html', '.htm', '.jsx', '.tsx')):
                if not check_js_html_functions(file_path):
                    return False
            # 同样兼容可能生成的基于缩进的 Python 后台文件
            elif file.endswith('.py'):
                if not check_py_functions(file_path):
                    return False

    return True

