import os
import re

def check_indentation(response: str, workspace_path: str) -> bool:
    codes = []

    # 从工作区路径中获取文件代码内容
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        for root, dirs, files in os.walk(workspace_path):
            for file in files:
                if file.endswith(('.html', '.css', '.js')):
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            codes.append(f.read())
                    except Exception:
                        pass

    # 从回复内容中提取 Markdown 格式的代码块
    code_blocks = re.findall(r'```[a-zA-Z]*\n(.*?)```', response, re.DOTALL)
    codes.extend(code_blocks)

    # 如果没有找到任何代码，返回 False
    if not codes:
        return False

    for code in codes:
        lines = code.split('\n')
        for line in lines:
            # 跳过空行或全空白行
            if not line.strip():
                continue

            # 获取行首的前导空白
            leading_space = line[:len(line) - len(line.lstrip())]

            # 如果包含制表符，视为违反要求
            if '\t' in leading_space:
                return False

            # 如果空格数量不是4的倍数，检查是否为注释排版，如果不是则违反要求
            if len(leading_space) % 4 != 0:
                stripped_line = line.lstrip()
                # 豁免多行注释的对齐排版（如以 *、/*、<!--、// 开头的行）
                if (stripped_line.startswith('*') or 
                    stripped_line.startswith('/*') or 
                    stripped_line.startswith('<!--') or 
                    stripped_line.startswith('//')):
                    continue
                return False

    return True

