def verify(response: str, workspace_path: str) -> bool:
    import os
    import re

    def clean_js_code(code: str) -> str:
        """
        利用状态机清洗JS代码，将字符串内容和注释替换为空格，但完整保留换行符
        """
        state = 'NORMAL'
        cleaned = []
        i = 0
        n = len(code)
        quote_char = ''

        while i < n:
            c = code[i]
            if state == 'NORMAL':
                if c == '/' and i + 1 < n and code[i+1] == '/':
                    state = 'LINE_COMMENT'
                    cleaned.extend([' ', ' '])
                    i += 2
                    continue
                elif c == '/' and i + 1 < n and code[i+1] == '*':
                    state = 'BLOCK_COMMENT'
                    cleaned.extend([' ', ' '])
                    i += 2
                    continue
                elif c in ('"', "'", '`'):
                    state = 'STRING'
                    quote_char = c
                    cleaned.append(c)
                    i += 1
                    continue
                else:
                    cleaned.append(c)
                    i += 1
            elif state == 'LINE_COMMENT':
                if c == '\n':
                    state = 'NORMAL'
                    cleaned.append(c)
                else:
                    cleaned.append(' ')
                i += 1
            elif state == 'BLOCK_COMMENT':
                if c == '*' and i + 1 < n and code[i+1] == '/':
                    state = 'NORMAL'
                    cleaned.extend([' ', ' '])
                    i += 2
                    continue
                elif c == '\n':
                    cleaned.append(c)
                else:
                    cleaned.append(' ')
                i += 1
            elif state == 'STRING':
                if c == '\\':
                    cleaned.extend([' ', ' '])
                    i += 2
                    continue
                elif c == quote_char:
                    state = 'NORMAL'
                    cleaned.append(c)
                    i += 1
                elif c == '\n':
                    cleaned.append(c)
                    i += 1
                else:
                    cleaned.append(' ')
                    i += 1
        return "".join(cleaned)

    def get_function_blocks(clean_code: str):
        """
        从清洗过的 JS 代码中寻找函数，并通过大括号匹配计算它的行数
        """
        open_braces = [i for i, c in enumerate(clean_code) if c == '{']
        blocks = []
        ignore_keywords = {'if', 'for', 'while', 'catch', 'switch', 'with'}

        for start_idx in open_braces:
            prefix_start = max(0, start_idx - 200)
            prefix = clean_code[prefix_start:start_idx]

            is_func = False
            sig_start = start_idx

            # 使用正则表达式匹配不同类型的函数声明方式
            m_func = re.search(r'\bfunction\b[^{]*$', prefix)
            m_arrow = re.search(r'=>\s*$', prefix)
            m_method = re.search(r'\b([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\([^)]*\)\s*$', prefix)

            if m_func:
                is_func = True
                sig_start = prefix_start + m_func.start()
            elif m_arrow:
                is_func = True
                m_arrow_full = re.search(r'(\([^)]*\)\s*=>\s*)$|([a-zA-Z_$][a-zA-Z0-9_$]*\s*=>\s*)$', prefix)
                if m_arrow_full:
                    sig_start = prefix_start + m_arrow_full.start()
                else:
                    sig_start = prefix_start + m_arrow.start()
            elif m_method:
                if m_method.group(1) not in ignore_keywords:
                    is_func = True
                    sig_start = prefix_start + m_method.start()

            if is_func:
                brace_count = 1
                end_idx = -1
                for i in range(start_idx + 1, len(clean_code)):
                    if clean_code[i] == '{':
                        brace_count += 1
                    elif clean_code[i] == '}':
                        brace_count -= 1
                        if brace_count == 0:
                            end_idx = i
                            break

                if end_idx != -1:
                    # 获取该函数起止位置之间的换行符数量计算行数
                    lines = clean_code.count('\n', sig_start, end_idx) + 1
                    blocks.append(lines)

        return blocks

    def check_file(filepath: str) -> bool:
        """
        检查单文件，提取需要判断的代码并返回行数是否均<=60
        """
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception:
            return True

        # 根据文件类型提取需要进行解析验证的 JavaScript 代码部分
        if filepath.endswith('.html'):
            scripts = re.findall(r'<script.*?>\s*(.*?)\s*</script>', content, re.IGNORECASE | re.DOTALL)
            code_to_check = "\n".join(scripts)
        elif filepath.endswith(('.js', '.ts')):
            code_to_check = content
        else:
            return True

        if not code_to_check.strip():
            return True

        clean_code = clean_js_code(code_to_check)
        blocks = get_function_blocks(clean_code)

        for lines in blocks:
            if lines > 60:
                return False

        return True

    # 遍历项目文件，一旦发现有规模超过60行的函数，立即判断为违背要求
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if file.endswith(('.js', '.ts', '.html')):
                filepath = os.path.join(root, file)
                if not check_file(filepath):
                    return False

    return True

def verify(response: str, workspace_path: str) -> bool:
    """
    验证AI的回复是否在结尾处加上了"哒～"语气词。
    """
    if not response:
