def check_requirements(response: str, workspace_path: str) -> bool:
    code_lines = []
    has_files = False

    # 1. 尝试读取工作区中生成的代码文件
    if os.path.exists(workspace_path) and os.path.isdir(workspace_path):
        for root, _, files in os.walk(workspace_path):
            for file in files:
                # 针对指令中提到的前端相关技术栈进行检验
                if file.endswith(('.html', '.css', '.js')):
                    has_files = True
                    try:
                        with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                            code_lines.extend(f.readlines())
                    except Exception:
                        pass

    # 2. 如果工作区没有对应文件，则降级尝试从回复中提取代码块
    if not has_files:
        code_blocks = re.findall(r'```(?:html|css|javascript|js)?\n(.*?)```', response, re.DOTALL | re.IGNORECASE)
        for block in code_blocks:
            code_lines.extend(block.split('\n'))

    # 如果完全没有代码生成，则视为未完成要求
    if not code_lines:
        return False

    has_2_space_indent = False
    has_valid_indent = False

    for line in code_lines:
        # 跳过空行
        if not line.strip():
            continue

        # 匹配行首所有的空格和制表符
        match = re.match(r'^([ \t]+)(.*)', line)
        if match:
            indent = match.group(1)
            content = match.group(2)

            # 不允许使用制表符作为缩进
            if '\t' in indent:
                return False

            indent_len = len(indent)

            # 缩进不允许为奇数（但宽容对待多行注释等对齐带来的特殊情况）
            if indent_len % 2 != 0:
                if not (content.startswith('*') or content.startswith('<!--') or content.startswith('-->')):
                    return False
                continue

            if indent_len > 0:
                has_valid_indent = True
                # 若存在长度无法被 4 整除的偶数缩进（如 2, 6, 10），证明使用的是2个空格为基准的缩进
                if indent_len % 4 != 0:
                    has_2_space_indent = True

    # 代码中必须存在有效的缩进，且确认其体现了2个空格的缩进特性（而非混水摸鱼全保留为4个空格）
    return has_valid_indent and has_2_space_indent

