import os
import re

def verify_function_length(response: str, workspace_path: str) -> bool:
    def check_code_string(code: str, is_html: bool) -> bool:
        if is_html:
            # 对于HTML文件，将<script>外的部分替换为空白行，以确保真实的JS行号不会丢失
            out = []
            idx = 0
            for m in re.finditer(r'(?i)<script[^>]*>([\s\S]*?)</script>', code):
                start = m.start(1)
                end = m.end(1)
                out.append('\n' * code[idx:start].count('\n'))
                out.append(code[start:end])
                idx = end
            out.append('\n' * code[idx:].count('\n'))
            code = "".join(out)

        # 匹配词法单元的正则，使用了 re.DOTALL 使得 . 可以匹配换行符
        pattern = re.compile(
            r'(?P<multi_comment>/\*.*?\*/)|'
            r'(?P<single_comment>//[^\n]*)|'
            r'(?P<string1>\'(?:\\.|[^\\\'])*\')|'
            r'(?P<string2>\"(?:\\.|[^\\\"])*\")|'
            r'(?P<string3>`(?:\\.|[^`])*`)|'
            r'(?P<arrow>=>)|'
            r'(?P<word>[a-zA-Z_$][a-zA-Z0-9_$]*)|'
            r'(?P<punct>[{}()])|'
            r'(?P<newline>\n)',
            re.DOTALL
        )

        tokens = []
        current_line = 1
        for m in pattern.finditer(code):
            if m.lastgroup == 'newline':
                current_line += 1
            elif m.lastgroup in ('multi_comment', 'string1', 'string2', 'string3'):
                # 注释和字符串可能跨越多行，在此更新行号
                current_line += m.group().count('\n')
            elif m.lastgroup == 'word':
                tokens.append(('WORD', m.group(), current_line))
            elif m.lastgroup == 'arrow':
                tokens.append(('ARROW', '=>', current_line))
            elif m.lastgroup == 'punct':
                tokens.append(('PUNCT', m.group(), current_line))

        stack = []
        for i, token in enumerate(tokens):
            typ, val, line = token
            if typ == 'PUNCT' and val == '{':
                is_func = False
                func_start_line = line
                if i > 0:
                    prev_typ, prev_val, prev_line = tokens[i-1]
                    # 匹配箭头函数
                    if prev_typ == 'ARROW':
                        is_func = True
                        func_start_line = prev_line
                        # 尝试向前溯源参数括号的起始行
                        if i > 1 and tokens[i-2][1] == ')':
                            paren_count = 1
                            k = i - 3
                            while k >= 0:
                                if tokens[k][1] == ')': paren_count += 1
                                elif tokens[k][1] == '(': 
                                    paren_count -= 1
                                    if paren_count == 0:
                                        func_start_line = tokens[k][2]
                                        break
                                k -= 1
                        elif i > 1 and tokens[i-2][0] == 'WORD':
                            func_start_line = tokens[i-2][2]

                    # 匹配普通函数、类方法等
                    elif prev_typ == 'PUNCT' and prev_val == ')':
                        paren_count = 1
                        j = i - 2
                        while j >= 0:
                            if tokens[j][0] == 'PUNCT' and tokens[j][1] == ')':
                                paren_count += 1
                            elif tokens[j][0] == 'PUNCT' and tokens[j][1] == '(':
                                paren_count -= 1
                                if paren_count == 0:
                                    break
                            j -= 1

                        if j >= 0:
                            if j > 0:
                                before_paren = tokens[j-1]
                                if before_paren[0] == 'WORD':
                                    # 排除常规的控制流结构，剩余的大多为函数标识或方法名
                                    if before_paren[1] not in ('if', 'for', 'while', 'switch', 'catch', 'with'):
                                        is_func = True
                                        func_start_line = before_paren[2]
                                        # 如果方法名前还有 function/get/set 关键字等，更准确记录起行
                                        if j - 2 >= 0 and tokens[j-2][0] == 'WORD' and tokens[j-2][1] in ('function', 'get', 'set', 'static'):
                                            func_start_line = tokens[j-2][2]
                                else:
                                    # 针对无名称函数(例如：`function() { ... }`)
                                    is_func = True
                                    func_start_line = tokens[j][2]
                            else:
                                is_func = True
                                func_start_line = tokens[j][2]

                stack.append((is_func, func_start_line))
            elif typ == 'PUNCT' and val == '}':
                if stack:
                    is_func, start_line = stack.pop()
                    if is_func:
                        func_length = line - start_line + 1
                        # 要求：单个函数的规模不得大于 60 行
                        if func_length > 60:
                            return False
        return True

    # 1. 检查工作空间下所有生成的代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if file.endswith('.js') or file.endswith('.html'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue
                is_html = file.endswith('.html')
                if not check_code_string(content, is_html):
                    return False

    # 2. 兜底检查 AI 最后一轮回复中包含的代码片段
    blocks = re.finditer(r'```(?P<lang>[a-zA-Z0-9_-]+)?\n(?P<code>[\s\S]*?)```', response)
    for m in blocks:
        lang = (m.group('lang') or '').lower()
        code = m.group('code')
        if lang in ('js', 'javascript'):
            if not check_code_string(code, is_html=False): return False
        elif lang in ('html', 'htm'):
            if not check_code_string(code, is_html=True): return False
        else:
            # 针对语言未明示的片段进行兜底探测
            if '<html' in code.lower() or '<script' in code.lower():
                if not check_code_string(code, is_html=True): return False
            elif 'function' in code or '=>' in code:
                if not check_code_string(code, is_html=False): return False

    return True

