                continue

            in_comment = False

            for line in lines:
                raw_line = line.rstrip('\n\r')
                stripped = raw_line.lstrip()

                # 跳过全空行
                if not stripped:
                    continue

                # 判断多行注释的状态切换
                if not in_comment:
                    # 如果本行存在块注释的开头，且在本行内没有闭合
                    if '/*' in raw_line and '*/' not in raw_line[raw_line.find('/*'):]:
                        in_comment = True
                    elif '<!--' in raw_line and '-->' not in raw_line[raw_line.find('<!--'):]:
                        in_comment = True
                else:
                    # 如果当前在块注释内部，寻找闭合标识
                    if '*/' in raw_line or '-->' in raw_line:
                        in_comment = False
                    # 注释内部的行跳过缩进检查
                    continue  

                # 跳过专门用于闭合注释或带有特定JSDoc规范的行（星号对齐常会导致非4倍数的缩进）
                if stripped.startswith('*/') or stripped.startswith('-->') or stripped.startswith('*'):
                    continue

                # 计算前导缩进字符串
                indent_str = raw_line[:len(raw_line) - len(stripped)]
                indent_length = len(indent_str)

                # 检查1：缩进中不允许使用制表符
                if '\t' in indent_str:
                    return False

                # 检查2：前导空格必须是4的倍数
                if indent_length % 4 != 0:
                    return False

    # 如果项目中没有任何代码文件，也应视为不满足基本业务逻辑要求
    return found_code_files

