def verify(response: str, workspace_path: str) -> bool:
    def get_lines_count(code: str, start_pos: int, end_pos: int) -> int:
        start_line = code.count('\n', 0, start_pos) + 1
        end_line = code.count('\n', 0, end_pos) + 1
        return end_line - start_line + 1

    def check_functions(code: str) -> bool:
        # 1. 去除注释和字符串字面量的干扰，但严格保留换行符以确保行数计算准确
        result = []
        i = 0
        n = len(code)
        state = 'NORMAL'
        while i < n:
            c = code[i]
            if state == 'NORMAL':
                if c == '/' and i + 1 < n and code[i+1] == '/':
                    state = 'LINE_COMMENT'
                    result.append(' ')
                    result.append(' ')
                    i += 2
                    continue
                elif c == '/' and i + 1 < n and code[i+1] == '*':
                    state = 'BLOCK_COMMENT'
                    result.append(' ')
                    result.append(' ')
                    i += 2
                    continue
                elif c == "'":
                    state = 'SINGLE_QUOTE'
                    result.append(' ')
                    i += 1
                    continue
                elif c == '"':
                    state = 'DOUBLE_QUOTE'
                    result.append(' ')
                    i += 1
                    continue
                elif c == '`':
                    state = 'TEMPLATE_QUOTE'
                    result.append(' ')
                    i += 1
                    continue
                else:
                    result.append(c)
                    i += 1
            elif state == 'LINE_COMMENT':
                if c == '\n':
                    state = 'NORMAL'
                    result.append(c)
                else:
                    result.append(' ')
                i += 1
            elif state == 'BLOCK_COMMENT':
                if c == '*' and i + 1 < n and code[i+1] == '/':
                    state = 'NORMAL'
                    result.append(' ')
                    result.append(' ')
                    i += 2
                else:
                    result.append('\n' if c == '\n' else ' ')
                    i += 1
            elif state == 'SINGLE_QUOTE':
                if c == '\\':
                    result.append(' ')
                    result.append(' ')
                    i += 2
                elif c == "'":
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    result.append('\n' if c == '\n' else ' ')
                    i += 1
            elif state == 'DOUBLE_QUOTE':
                if c == '\\':
                    result.append(' ')
                    result.append(' ')
                    i += 2
                elif c == '"':
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    result.append('\n' if c == '\n' else ' ')
                    i += 1
            elif state == 'TEMPLATE_QUOTE':
                if c == '\\':
                    result.append(' ')
                    result.append(' ')
                    i += 2
                elif c == '`':
                    state = 'NORMAL'
                    result.append(' ')
                    i += 1
                else:
                    result.append('\n' if c == '\n' else ' ')
                    i += 1

        clean_code = "".join(result)

        # 2. 提取干净代码中的 Token 及它的真实起始下标
        tokens = []
        pattern = re.compile(r'=>|[a-zA-Z_$][a-zA-Z0-9_$]*|\S')
        for match in pattern.finditer(clean_code):
            tokens.append((match.group(0), match.start()))

        # 3. 判断并找出函数的修饰符起点
        def get_function_start(tokens, i):
            if i == 0: return -1
            prev_tok = tokens[i-1][0]

            # 处理箭头函数
            if prev_tok == '=>':
                if i >= 2 and tokens[i-2][0] == ')':
                    paren_count = 1
                    j = i - 3
                    while j >= 0 and paren_count > 0:
                        if tokens[j][0] == ')': paren_count += 1
                        elif tokens[j][0] == '(': paren_count -= 1
                        j -= 1
                    if j >= 0 and tokens[j][0] == 'async':
                        return j
                    return j + 1
                else:
                    j = i - 2
                    if j >= 0 and tokens[j][0] == 'async':
                        return j
                    return i - 2

            # 异常极端的 function 无括号定义
            if prev_tok == 'function':
                if i >= 2 and tokens[i-2][0] == 'async':
                    return i - 2
                return i - 1

            # 处理常见函数 function(), method() 等
            if prev_tok == ')':
                paren_count = 1
                j = i - 2
                while j >= 0 and paren_count > 0:
                    if tokens[j][0] == ')': paren_count += 1
                    elif tokens[j][0] == '(': paren_count -= 1
                    j -= 1
                if j >= 0:
                    before_paren = tokens[j][0]
                    # 过滤流程控制关键字
                    if before_paren in {'if', 'for', 'while', 'switch', 'catch', 'with'}:
                        return -1
                    if before_paren == 'function':
                        if j >= 1 and tokens[j-1][0] == 'async':
                            return j - 1
                        return j
                    if before_paren == '*':
                        if j >= 1 and tokens[j-1][0] == 'function':
                            if j >= 2 and tokens[j-2][0] == 'async':
                                return j - 2
                            return j - 1
                        return -1
                    # 对象方法, class 方法，get/set 等
                    if re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', before_paren):
                        if j >= 1 and tokens[j-1][0] == 'function':
                            if j >= 2 and tokens[j-2][0] == 'async':
                                return j - 2
                            return j - 1
                        if j >= 2 and tokens[j-1][0] == '*' and tokens[j-2][0] == 'function':
                            if j >= 3 and tokens[j-3][0] == 'async':
                                return j - 3
                            return j - 2
                        if j >= 1 and tokens[j-1][0] in {'get', 'set', 'async'}:
                            return j - 1
                        return j
                    return -1
                else:
                    return -1
            return -1

        # 4. 利用大括号的配对，结合位置信息计算函数行数
        stack = []
        for i, (tok, pos) in enumerate(tokens):
            if tok == '{':
                func_start_idx = get_function_start(tokens, i)
                stack.append((func_start_idx, pos))
            elif tok == '}':
                if stack:
                    func_start_idx, brace_pos = stack.pop()
                    if func_start_idx != -1:
                        start_pos = tokens[func_start_idx][1]
                        end_pos = pos
                        if get_lines_count(code, start_pos, end_pos) > 60:
                            return False
        return True

    # 遍历项目文件中的 JavaScript (.js, .ts) 与内嵌的 Html script 标签
    for root_dir, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root_dir, file)
            if file.endswith(('.js', '.ts')):
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        code = f.read()
                    if not check_functions(code):
                        return False
                except Exception:
                    pass
            elif file.endswith('.html'):
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    script_matches = re.finditer(r'<script.*?>([\s\S]*?)</script>', content, re.IGNORECASE)
                    for match in script_matches:
                        script_code = match.group(1)
                        if not check_functions(script_code):
                            return False
                except Exception:
                    pass

    return True

