def check_indentation_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    code_extensions = {'.html', '.css', '.js'}
    has_code_file = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                has_code_file = True
                filepath = os.path.join(root, file)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                valid_indent = 0
                invalid_indent = 0

                for line in lines:
                    stripped = line.lstrip()
                    # 忽略完全为空白字符的行
                    if not stripped:
                        continue
                    # 忽略多行注释中为了美观以 '*' 及其后带空格对齐的中间行
                    if stripped.startswith('*'):
                        continue

                    # 匹配行首的连续空白字符
                    match = re.match(r'^([ \t]+)', line)
                    if match:
                        indent = match.group(1)
                        # 一旦存在制表符，直接判定未满足“完全由4个空格组成”的要求
                        if '\t' in indent:
                            return False

                        # 验证空格长度是否为4的倍数
                        if len(indent) % 4 == 0:
                            valid_indent += 1
                        else:
                            invalid_indent += 1

                total_indent = valid_indent + invalid_indent
                if total_indent > 0:
                    # 设置合理的容错阈值（10%及最多2行）：
                    # 处理诸如 HTML 标签属性换行引发的少许非常规对齐。
                    # 如果仍大量存在2个空格的缩进，invalid_indent 的数量会显著超标，直接返回 False。
                    if invalid_indent > max(2, total_indent * 0.1):
                        return False

    # 必须至少验证过一个代码文件，且全部符合检查逻辑才判定为 True
    return True if has_code_file else False

def check(response: str, workspace_path: str) -> bool:
