                if ext in code_exts:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            first_line = f.readline()
                            # 必须包含该编码声明，否则不满足条件
                            if not first_line or "-*- coding: utf-8 -*-" not in first_line:
                                return False
                            files_checked = True
                    except Exception:
                        # 文件无法以utf-8正确读取或其他异常，认定不满足要求
                        return False

    # 如果在工作区中检测到了代码文件并且全部检查通过，判定为满足
    if files_checked:
        return True

    # 如果工作区中没有实体代码文件，降级检查回复内容中的代码块
    code_blocks = re.findall(r'```([a-zA-Z0-9]*)\n(.*?)```', response, re.DOTALL)
    blocks_checked = False
    target_langs = {'html', 'css', 'javascript', 'js', 'typescript', 'ts', 'python', 'py', 'java', 'c', 'cpp'}

    for lang, code in code_blocks:
        lang = lang.strip().lower()
        if lang in target_langs:
            lines = code.split('\n')
            if not lines:
                return False
            first_line = lines[0]
