def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re
    import bisect

    # 将所有可能干扰大括号配对的字符串和注释替换为空格，但保留换行符，以便准确计算行号
    def get_clean_code(code: str) -> str:
        def replacer(match):
            s = match.group(0)
            return ''.join(['\n' if c == '\n' else ' ' for c in s])

        pattern = r'(/\*.*?\*/)|(//[^\n]*)|("(?:\\.|[^"\\])*")|(\'(?:\\.|[^\'\\])*\')|(`(?:\\.|[^`\\])*`)'
        clean_code = re.sub(pattern, replacer, code, flags=re.DOTALL)
        return clean_code

    # 利用换行符的索引表快速推断任意字符 index 所处的行号
    def get_line_number(index: int, line_starts: list) -> int:
        return bisect.bisect_right(line_starts, index)

    # 判断当前 { 是否是一个函数体的开始，并尝试返回函数声明的起始索引
    def check_is_function_start(clean_code: str, index: int):
        p = index - 1
        while p >= 0 and clean_code[p] in ' \t\n\r':
            p -= 1
        if p < 0:
            return False, -1

        # 1. 判断是否为箭头函数 =>
        if clean_code[p] == '>' and p > 0 and clean_code[p-1] == '=':
            q = p - 2
            while q >= 0 and clean_code[q] in ' \t\n\r':
                q -= 1
            if q >= 0 and clean_code[q] == ')':
                paren_count = 1
                q -= 1
                while q >= 0 and paren_count > 0:
                    if clean_code[q] == ')':
                        paren_count += 1
                    elif clean_code[q] == '(':
                        paren_count -= 1
                    q -= 1
                if q >= 0:
                    return True, q + 1
            return True, p - 1

        # 2. 判断是否为普通函数，或者类的方法、对象的方法，形如 function(...) 或 myMethod(...)
        if clean_code[p] == ')':
            paren_count = 1
            p -= 1
            while p >= 0 and paren_count > 0:
                if clean_code[p] == ')':
                    paren_count += 1
                elif clean_code[p] == '(':
                    paren_count -= 1
                p -= 1

            if p < 0:
                return False, -1

            left_paren_index = p + 1
            while p >= 0 and clean_code[p] in ' \t\n\r':
                p -= 1

            if p < 0:
                return False, -1

            word_end = p
            # 提取前置单词（包含字母数字以及下划线或 $）
            while p >= 0 and (clean_code[p].isalnum() or clean_code[p] in '_$'):
                p -= 1

            word_start = p + 1
            word = clean_code[word_start:word_end+1]

            # 排除由于控制流引起的大括号
            if word in {'if', 'for', 'while', 'switch', 'catch', 'with'}:
                return False, -1
            if word == 'function':
                return True, word_start
            # 常规的方法名
            if word:
                return True, word_start

            return False, -1

        return False, -1

    # 获取某个左大括号对应的闭合右大括号索引
    def get_block_end(clean_code: str, start_index: int) -> int:
        brace_count = 1
        p = start_index + 1
        n = len(clean_code)
        while p < n and brace_count > 0:
            if clean_code[p] == '{':
                brace_count += 1
            elif clean_code[p] == '}':
                brace_count -= 1
            p += 1
        return p - 1

    def process_code(code: str) -> bool:
        clean_code = get_clean_code(code)
        # 构建所有换行符后面第一个字符的索引，0表示第一行开头
        line_starts = [0] + [m.start() + 1 for m in re.finditer('\n', clean_code)]

        n = len(clean_code)
        for i in range(n):
            if clean_code[i] == '{':
                is_func, func_start = check_is_function_start(clean_code, i)
                if is_func and func_start >= 0:
                    block_end = get_block_end(clean_code, i)
                    if block_end < n:
                        start_line = get_line_number(func_start, line_starts)
                        end_line = get_line_number(block_end, line_starts)
                        # 判断该函数行数是否超过 60 行
                        if end_line - start_line + 1 > 60:
                            return False
        return True

    # 检查工作空间路径
    if not os.path.exists(workspace_path) or not os.path.isdir(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_lower = file.lower()
            if file_lower.endswith('.js'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    if not process_code(content):
                        return False
                except Exception:
                    return False
            elif file_lower.endswith('.html'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    # 匹配 HTML 中的 <script> 标签内的 JS 代码并检查
                    scripts = re.findall(r'<script[^>]*>(.*?)</script>', content, flags=re.DOTALL | re.IGNORECASE)
                    for script_content in scripts:
                        if script_content.strip():
                            if not process_code(script_content):
                                return False
                except Exception:
                    return False

    return True

def check(response: str, workspace_path: str) -> bool:
    import re

    if not response:
        return False

    # \W 匹配非单词字符（包含了标点符号和空白字符），$ 匹配字符串末尾
    # 这个正则表示在字符串结尾处必须包含“哒～”，其后允许跟随任意标点或空白
    match = re.search(r'哒～\W*$', response.strip())

    return bool(match)

