def check_indentation_is_2_spaces(response: str, workspace_path: str) -> bool:
    # 定义常见的代码文件后缀。
    # 排除 .md、.json 等文档或数据文件，只针对真正手写的“代码文件”。
    code_exts = {
        '.js', '.html', '.css', '.py', '.ts', 
        '.jsx', '.tsx', '.c', '.cpp', '.java', '.go', '.rs'
    }
    has_code_file = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_exts:
                has_code_file = True
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                even_indents = set()
                indent_counts = {}

                for line in lines:
                    stripped = line.lstrip('\n\r')
                    if not stripped.strip():
                        continue

                    # 忽略以 * 开头的多行注释，避免注释里的特殊对齐（如 ` * `）造成干扰
                    if stripped.lstrip().startswith('*'):
                        continue

                    # 提取行首的空白字符
                    leading_chars = line[:len(line) - len(line.lstrip())]

                    # 严格要求：不能包含 Tab 制表符
                    if '\t' in leading_chars:
                        return False

                    length = len(leading_chars)

                    # 为了过滤掉变量对齐、HTML属性换行对齐等可能产生的奇数个空格（如3或5个空格），
                    # 我们重点收集和校验偶数个空格的分布。
                    if length > 0 and length % 2 == 0:
                        even_indents.add(length)
                        indent_counts[length] = indent_counts.get(length, 0) + 1

                if even_indents:
                    # 如果该文件收集到的所有偶数缩进，全部都是 4 的倍数 (如 4, 8, 12... 没有任何 2, 6, 10...)
                    if all(i % 4 == 0 for i in even_indents):
                        total_even_indented_lines = sum(indent_counts.values())
                        # 为防止代码文件仅有1~2行长代码续行导致的偶发4空格被误判，
                        # 只有当包含足够的缩进行（>=3行）时，才断定该文件依然采用了4个空格的缩进风格。
                        if total_even_indented_lines >= 3:
                            return False

    return has_code_file

