def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re
    import ast

    def mask_code(code: str) -> str:
        """屏蔽注释和字符串字面量以防误判，但保留所有的换行符以确保行号不变"""
        masked_code = []
        in_block_comment = False
        in_string = False
        string_char = ''
        in_template = False

        i = 0
        while i < len(code):
            if in_block_comment:
                if i + 1 < len(code) and code[i:i+2] == '*/':
                    in_block_comment = False
                    masked_code.append('  ')
                    i += 2
                else:
                    masked_code.append('\n' if code[i] == '\n' else ' ')
                    i += 1
            elif in_string:
                if code[i] == '\\':
                    masked_code.append('  ')
                    i += 2
                elif code[i] == string_char:
                    in_string = False
                    masked_code.append(' ')
                    i += 1
                else:
                    masked_code.append('\n' if code[i] == '\n' else ' ')
                    i += 1
            elif in_template:
                if code[i] == '\\':
                    masked_code.append('  ')
                    i += 2
                elif code[i] == '`':
                    in_template = False
                    masked_code.append(' ')
                    i += 1
                else:
                    masked_code.append('\n' if code[i] == '\n' else ' ')
                    i += 1
            else:
                if i + 1 < len(code) and code[i:i+2] == '/*':
                    in_block_comment = True
                    masked_code.append('  ')
                    i += 2
                elif i + 1 < len(code) and code[i:i+2] == '//':
                    # Skip until newline
                    while i < len(code) and code[i] != '\n':
                        masked_code.append(' ')
                        i += 1
                elif code[i] in ["'", '"']:
                    in_string = True
                    string_char = code[i]
                    masked_code.append(' ')
                    i += 1
                elif code[i] == '`':
                    in_template = True
                    masked_code.append(' ')
                    i += 1
                else:
                    masked_code.append(code[i])
                    i += 1

        return "".join(masked_code)

    def check_js_functions(code: str, max_lines: int = 60) -> bool:
        masked_code_str = mask_code(code)
        masked_lines = masked_code_str.split('\n')

        # 常见的三种 JS/TS 包含大括号的函数起始声明特征
        func_pattern1 = re.compile(r'\bfunction\b')
        func_pattern2 = re.compile(r'=>\s*\{')
        func_pattern3 = re.compile(r'^\s*(async\s+)?[\w\$]+\s*\([^)]*\)\s*\{')

        i = 0
        while i < len(masked_lines):
            line = masked_lines[i]
            is_func_start = False

            if func_pattern1.search(line) or func_pattern2.search(line) or func_pattern3.search(line):
                is_func_start = True

            if is_func_start:
                start_line = i
                open_braces = 0

                j = i
                found_first_brace = False
                while j < len(masked_lines):
                    curr_line = masked_lines[j]

                    for char in curr_line:
                        if char == '{':
                            open_braces += 1
                            found_first_brace = True
                        elif char == '}':
                            open_braces -= 1

                    if found_first_brace and open_braces == 0:
                        end_line = j
                        func_len = end_line - start_line + 1
                        if func_len > max_lines:
                            return False
                        break
                    j += 1
            i += 1

        return True

    def check_python_functions(code: str, max_lines: int = 60) -> bool:
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return True # 若存在语法错误则忽略
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if hasattr(node, 'end_lineno'):
                    if (node.end_lineno - node.lineno + 1) > max_lines:
                        return False
        return True

    # 遍历项目下所有的源文件
    for root, _, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()

            if ext in ['.js', '.html', '.py']:
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        code = f.read()
                except Exception:
                    continue

                if ext == '.py':
                    if not check_python_functions(code):
                        return False
                elif ext == '.js':
                    if not check_js_functions(code):
                        return False
                elif ext == '.html':
                    script_pattern = re.compile(r'<script[^>]*>(.*?)</script>', re.IGNORECASE | re.DOTALL)
                    scripts = script_pattern.findall(code)
                    for script in scripts:
                        if not check_js_functions(script):
                            return False

    return True

