def check_requirements(response: str, workspace_path: str) -> bool:
    def remove_strings_and_comments(code: str) -> str:
        """
        移除代码中的字符串字面量和注释，但保留所有的换行符
        以确保代码的行号信息在处理前后保持严格一致。
        """
        result = []
        i = 0
        n = len(code)
        in_string = False
        string_char = ''
        in_scomment = False
        in_mcomment = False

        while i < n:
            if in_string:
                if code[i] == '\\':
                    # 如果转义字符后直接换行，需要保留换行符
                    if i + 1 < n and code[i+1] == '\n':
                        result.append('\n')
                    i += 2
                    continue
                elif code[i] == string_char:
                    in_string = False
                elif code[i] == '\n':
                    result.append('\n')
                i += 1
            elif in_scomment:
                if code[i] == '\n':
                    in_scomment = False
                    result.append('\n')
                i += 1
            elif in_mcomment:
                if code[i:i+2] == '*/':
                    in_mcomment = False
                    i += 2
                else:
                    if code[i] == '\n':
                        result.append('\n')
                    i += 1
            else:
                if code[i:i+2] == '//':
                    in_scomment = True
                    i += 2
                elif code[i:i+2] == '/*':
                    in_mcomment = True
                    i += 2
                elif code[i] in '"\'`':
                    in_string = True
                    string_char = code[i]
                    i += 1
                else:
                    result.append(code[i])
                    i += 1
        return "".join(result)

    def get_js_content(file_path: str, code: str) -> str:
        """
        如果文件是 HTML，则只提取 <script> 标签中的内容。
        将非脚本的部分替换为空行，以便保持 JavaScript 脚本在文件中的原始行号。
        """
        if file_path.endswith(('.html', '.htm')):
            in_script = False
            result = []
            lines = code.split('\n')
            for line in lines:
                lower_line = line.lower()
                if not in_script:
                    if '<script' in lower_line and 'src=' not in lower_line:
                        in_script = True
                        result.append(line)
                        if '</script>' in lower_line:
                            in_script = False
                    else:
                        result.append('') # 保持原有的行号一致性
                else:
                    result.append(line)
                    if '</script>' in lower_line:
                        in_script = False
            return '\n'.join(result)
        return code

    def check_functions(code: str) -> bool:
        """
        基于过滤后的代码，匹配函数作用域的 `{}` 并校验行数限制。
        """
        clean_code = remove_strings_and_comments(code)
        tokens = re.split(r'([{}\n])', clean_code)

        line_num = 1
        depth = 0
        buffer = ""
        active_functions = [] 

        for token in tokens:
            if token == '\n':
                line_num += 1
                buffer += token
            elif token == '{':
                depth += 1
                is_func = False

                # 检查在遇到大括号之前的 buffer 中是否具有函数的特征
                if re.search(r'\bfunction\b', buffer):
                    is_func = True
                elif re.search(r'=>\s*\(?\s*$', buffer):
                    is_func = True
                else:
                    # 匹配可能是类方法或者对象方法的定义如 "methodName(args) "
                    match = re.search(r'\b([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\((.*)\)\s*$', buffer, flags=re.DOTALL)
                    if match:
                        word = match.group(1)
                        # 排除常见的非函数关键词
                        if word not in ('if', 'for', 'while', 'switch', 'catch', 'with'):
                            is_func = True

                if is_func:
                    active_functions.append({'start_line': line_num, 'depth': depth})
                buffer = ""
            elif token == '}':
                # 遇到大括号闭合，检查是否有该深度下记录的函数
                for f in active_functions:
                    if f['depth'] == depth:
                        length = line_num - f['start_line'] + 1
                        if length > 60:
                            return False # 函数超出限制，直接返回False
                # 弹出当前深度下已经结束的函数
                active_functions = [f for f in active_functions if f['depth'] != depth]
                depth -= 1
                buffer = ""
            else:
                buffer += token

        return True

    # 遍历当前工作区的所有相关代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if file.endswith(('.js', '.ts', '.html', '.htm', '.jsx', '.tsx')):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        code = f.read()
                except Exception:
                    continue

                js_code = get_js_content(file_path, code)
                if not check_functions(js_code):
                    return False

    return True

