def clean_code(code: str) -> str:
    """
    清洗代码，将所有注释和字符串的内容替换为空格，
    保留换行符以确保代码文本的绝对位置和行号不变，便于准确提取函数体。
    """
    result = []
    i = 0
    n = len(code)
    while i < n:
        if code[i:i+2] == '//':
            result.append('//')
            i += 2
            while i < n and code[i] != '\n':
                result.append(' ')
                i += 1
        elif code[i:i+2] == '/*':
            result.append('/*')
            i += 2
            while i < n and code[i:i+2] != '*/':
                if code[i] == '\n':
                    result.append('\n')
                else:
                    result.append(' ')
                i += 1
            if i < n:
                result.append('  ')
                i += 2
        elif code[i] in '"\'`':
            quote = code[i]
            result.append(quote)
            i += 1
            while i < n and code[i] != quote:
                if code[i] == '\\':
                    result.append('  ')
                    i += 2
                else:
                    if code[i] == '\n':
                        result.append('\n')
                    else:
                        result.append(' ')
                    i += 1
            if i < n:
                result.append(quote)
                i += 1
        else:
            result.append(code[i])
            i += 1
    return "".join(result)

def check_function_lengths(code: str, max_lines: int = 60) -> bool:
    """
    检查给定代码中所有函数的行数是否符合要求
    """
    cleaned = clean_code(code)
    n = len(cleaned)
    for i in range(n):
        if cleaned[i] == '{':
            is_func = False
            start_pos = i

            j = i - 1
            while j >= 0 and cleaned[j].isspace():
                j -= 1
            if j < 0:
                continue

            char1 = cleaned[j]
            # 判断箭头函数 => {
            if char1 == '>':
                if j >= 1 and cleaned[j-1] == '=':
                    is_func = True
                    p = j - 2
                    while p >= 0 and cleaned[p].isspace():
                        p -= 1
                    # 尝试前向匹配箭头函数的参数括号 ( )
                    if p >= 0 and cleaned[p] == ')':
                        paren_count = 0
                        k = p
                        while k >= 0:
                            if cleaned[k] == ')':
                                paren_count += 1
                            elif cleaned[k] == '(':
                                paren_count -= 1
                                if paren_count == 0:
                                    break
                            k -= 1
                        if k >= 0:
                            start_pos = k
                        else:
                            start_pos = j - 1
                    else:
                        start_pos = j - 1

            # 判断普通函数、类方法等 ) {
            elif char1 == ')':
                paren_count = 0
                k = j
                while k >= 0:
                    if cleaned[k] == ')':
                        paren_count += 1
                    elif cleaned[k] == '(':
                        paren_count -= 1
                        if paren_count == 0:
                            break
                    k -= 1
                if k >= 0:
                    p = k - 1
                    while p >= 0 and cleaned[p].isspace():
                        p -= 1

                    # 跳过可能存在的生成器前缀 *
                    if p >= 0 and cleaned[p] == '*':
                        p -= 1
                        while p >= 0 and cleaned[p].isspace():
                            p -= 1

                    # 获取函数或控制流名称
                    if p >= 0 and (cleaned[p].isalnum() or cleaned[p] in '_$'):
                        word_end = p
                        while p >= 0 and (cleaned[p].isalnum() or cleaned[p] in '_$'):
                            p -= 1
                        word_start = p + 1
                        word = cleaned[word_start:word_end+1]

                        # 过滤掉所有包含括号的非函数控制流
                        if word not in ['if', 'for', 'while', 'catch', 'switch', 'with']:
                            is_func = True
                            start_pos = word_start

            # 若确认为函数，匹配右侧括号，计算具体行数
            if is_func:
                brace_count = 0
                match_end = -1
                for k in range(i, n):
                    if cleaned[k] == '{':
                        brace_count += 1
                    elif cleaned[k] == '}':
                        brace_count -= 1
                        if brace_count == 0:
                            match_end = k
                            break
                if match_end != -1:
                    lines = cleaned[start_pos:match_end+1].count('\n') + 1
                    if lines > max_lines:
                        return False
    return True

def extract_js_from_html(html: str) -> str:
    """提取 HTML 文件中的 <script> 代码"""
    scripts = re.findall(r'<script[^>]*>(.*?)</script>', html, re.DOTALL | re.IGNORECASE)
    return "\n".join(scripts)

