def verify(response: str, workspace_path: str) -> bool:
    import os
    import re
    import bisect

    def clean_js(code: str) -> str:
        """
        利用状态机将 JS 代码中的所有注释和字符串内容替换为空格，
        同时严格保留所有换行符，以便后续的行号计算精确无误。
        """
        res = []
        i = 0
        n = len(code)
        state = 'NORMAL'
        while i < n:
            if state == 'NORMAL':
                if i + 1 < n and code[i:i+2] == '//':
                    state = 'LINE_COMMENT'
                    res.append('  ')
                    i += 2
                elif i + 1 < n and code[i:i+2] == '/*':
                    state = 'BLOCK_COMMENT'
                    res.append('  ')
                    i += 2
                elif code[i] == "'":
                    state = 'STRING1'
                    res.append(' ')
                    i += 1
                elif code[i] == '"':
                    state = 'STRING2'
                    res.append(' ')
                    i += 1
                elif code[i] == '`':
                    state = 'STRING_TEMPLATE'
                    res.append(' ')
                    i += 1
                else:
                    res.append(code[i])
                    i += 1
            elif state == 'LINE_COMMENT':
                if code[i] == '\n':
                    state = 'NORMAL'
                    res.append('\n')
                else:
                    res.append(' ')
                i += 1
            elif state == 'BLOCK_COMMENT':
                if i + 1 < n and code[i:i+2] == '*/':
                    state = 'NORMAL'
                    res.append('  ')
                    i += 2
                else:
                    if code[i] == '\n':
                        res.append('\n')
                    else:
                        res.append(' ')
                    i += 1
            elif state in ['STRING1', 'STRING2', 'STRING_TEMPLATE']:
                # 统一处理三种字符串状态下的转义字符和结束标志
                if code[i] == '\\':
                    res.append(' ')
                    i += 1
                    if i < n:
                        if code[i] == '\n':
                            res.append('\n')
                        else:
                            res.append(' ')
                        i += 1
                elif (state == 'STRING1' and code[i] == "'") or \
                     (state == 'STRING2' and code[i] == '"') or \
                     (state == 'STRING_TEMPLATE' and code[i] == '`'):
                    state = 'NORMAL'
                    res.append(' ')
                    i += 1
                else:
                    if code[i] == '\n':
                        res.append('\n')
                    else:
                        res.append(' ')
                    i += 1
        return ''.join(res)

    def check_js_code(code: str) -> bool:
        cleaned = clean_js(code)

        # 构建行号映射
        line_starts = [0] + [m.end() for m in re.finditer(r'\n', cleaned)]
        def get_line(idx):
            return bisect.bisect_right(line_starts, idx)

        # 提取相关标识符与括号进行语法判定
        tokens = []
        for m in re.finditer(r'[a-zA-Z0-9_]+|=>|\{|\}|\(|\)', cleaned):
            tokens.append({
                'val': m.group(),
                'line': get_line(m.start())
            })

        # 预先匹配圆括号对
        paren_stack = []
        paren_pairs = {}
        for i, t in enumerate(tokens):
            if t['val'] == '(':
                paren_stack.append(i)
            elif t['val'] == ')':
                if paren_stack:
                    start = paren_stack.pop()
                    paren_pairs[start] = i
                    paren_pairs[i] = start

        brace_stack = []

        for i, t in enumerate(tokens):
            if t['val'] == '{':
                is_func = False
                # 判断当前的大括号是否为函数的起始
                if i > 0 and tokens[i-1]['val'] == '=>':
                    # 箭头函数
                    is_func = True
                elif i > 0 and tokens[i-1]['val'] == ')':
                    # 普通函数、匿名函数、对象方法、类方法
                    if (i - 1) in paren_pairs:
                        left_paren_idx = paren_pairs[i - 1]
                        if left_paren_idx > 0:
                            prev_val = tokens[left_paren_idx - 1]['val']
                            if prev_val == 'function':
                                is_func = True
                            elif prev_val not in ['if', 'for', 'while', 'switch', 'catch', 'with']:
                                # 是合法的标识符且不是控制流关键字，判定为方法声明
                                if re.match(r'^[a-zA-Z0-9_]+$', prev_val):
                                    is_func = True

                brace_stack.append((i, is_func))
            elif t['val'] == '}':
                if brace_stack:
                    start_i, is_func = brace_stack.pop()
                    if is_func:
                        start_line = tokens[start_i]['line']
                        end_line = t['line']
                        # 检查当前函数的行数规模
                        if end_line - start_line + 1 > 60:
                            return False
        return True

    def check_html_code(html_code: str) -> bool:
        script_pattern = re.compile(r'<script[^>]*>(.*?)</script>', re.IGNORECASE | re.DOTALL)
        for m in script_pattern.finditer(html_code):
            script_content = m.group(1)
            # 对于 HTML 中的每个内联 JS 块进行独立检查
            if not check_js_code(script_content):
                return False
        return True

    if not os.path.exists(workspace_path):
        return True

    # 遍历检查目标工作区内所有的 js 和 html 文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            if file.endswith('.js'):
                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        content = f.read()
                    if not check_js_code(content):
                        return False
                except Exception:
                    pass
            elif file.endswith('.html') or file.endswith('.htm'):
                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        content = f.read()
                    if not check_html_code(content):
                        return False
                except Exception:
                    pass

    return True

