def verify(response: str, workspace_path: str) -> bool:
    import os
    import ast
    import re

    def check_py_functions(code_str: str) -> bool:
        """检查 Python 文件中的单个函数规模是否大于 60 行"""
        try:
            tree = ast.parse(code_str)
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    if hasattr(node, 'lineno') and hasattr(node, 'end_lineno') and node.end_lineno:
                        lines = node.end_lineno - node.lineno + 1
                        if lines > 60:
                            return False
        except SyntaxError:
            pass
        return True

    def check_js_functions(code_str: str) -> bool:
        """启发式检查 JS/TS 文件中的单个函数规模是否大于 60 行"""
        def replacer(match):
            text = match.group(0)
            # 保持换行符数量不变以确保行号不会错位，其他字符替换为空格
            return '\n' * text.count('\n') + ' ' * (len(text) - text.count('\n'))

        # 匹配单行注释、多行注释、以及各种类型的字符串
        pattern = re.compile(
            r'//.*|'
            r'/\*[\s\S]*?\*/|'
            r"'[^'\\]*(?:\\.[^'\\]*)*'|"
            r'"[^"\\]*(?:\\.[^"\\]*)*"|'
            r'`[^`\\]*(?:\\.[^`\\]*)*`',
            re.MULTILINE
        )
        try:
            cleaned_code = pattern.sub(replacer, code_str)
        except Exception:
            cleaned_code = code_str

        line_num = 1
        brace_stack = []
        function_blocks = []

        # 记录大括号对 '{ ... }' 的起止行号
        for char in cleaned_code:
            if char == '\n':
                line_num += 1
            elif char == '{':
                brace_stack.append(line_num)
            elif char == '}':
                if brace_stack:
                    start_l = brace_stack.pop()
                    function_blocks.append((start_l, line_num))

        function_start_lines = set()

        # 匹配 `function` 关键字和 `=>` 箭头函数
        for match in re.finditer(r'\bfunction\b|=>', cleaned_code):
            idx = match.start()
            l_num = cleaned_code.count('\n', 0, idx) + 1
            # 将匹配行及其后续相邻行加入潜在函数起点集合，考虑换行书写习惯
            function_start_lines.update([l_num, l_num + 1, l_num + 2])

        # 匹配类方法/对象简写方法：如 methodName(args) { 
        # (排除if, for, while, switch, catch等关键字)
        for match in re.finditer(r'\b(?!(?:if|for|while|switch|catch)\b)\w+\s*\([^)]*\)\s*\{', cleaned_code):
            idx = match.start()
            l_num = cleaned_code.count('\n', 0, idx) + 1
            function_start_lines.update([l_num, l_num + 1])

        # 检查所有被判定为函数体的代码块的行数跨度
        for start_l, end_l in function_blocks:
            if any(l in function_start_lines for l in [start_l, start_l - 1, start_l - 2]):
                if end_l - start_l + 1 > 60:
                    return False
        return True

    def check_html_functions(code_str: str) -> bool:
        """检查 HTML 文件中 script 标签内部的 JS 函数规模"""
        scripts = re.findall(r'<script\b[^>]*>([\s\S]*?)</script>', code_str, re.IGNORECASE)
        for script_content in scripts:
            if not check_js_functions(script_content):
                return False
        return True

    if not os.path.exists(workspace_path):
        return True

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            ext = os.path.splitext(file)[1].lower()

            # 对可能生成的代码文件分类进行审查
            if ext == '.py':
                if not check_py_functions(content):
                    return False
            elif ext in ['.js', '.ts', '.jsx', '.tsx']:
                if not check_js_functions(content):
                    return False
            elif ext in ['.html', '.htm']:
                if not check_html_functions(content):
                    return False

    return True

def check_requirement(response: str, workspace_path: str) -> bool:
    import re

    if not response:
        return False

    # 去除回复末尾的空白字符以及常见的句末标点符号
    cleaned_response = re.sub(r'[\s。！？\!\?\.]+$', '', response)

    # 检查结尾是否为“哒～”（考虑到模型可能使用半角波浪线，增加兼容“哒~”）
    if cleaned_response.endswith("哒～") or cleaned_response.endswith("哒~"):
        return True

    return False

def check_code_indentation(response: str, workspace_path: str) -> bool:
    import os

    # 针对当前项目可能存在的代码文件类型
    code_extensions = {'.html', '.css', '.js', '.py'}
    has_code_file = False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if any(file.endswith(ext) for ext in code_extensions):
                has_code_file = True
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                except Exception:
                    continue

                for line in lines:
                    stripped = line.strip()
                    # 忽略纯空行
                    if not stripped:
                        continue

                    # 忽略以 * 开头的行，避免对 JS/CSS 中标准的多行注释排版产生误判
                    if stripped.startswith('*'):
                        continue

                    # 提取行首的连续空白字符
                    leading_spaces = ""
                    for c in line:
                        if c in (' ', '\t'):
                            leading_spaces += c
                        else:
                            break

                    # 检查是否包含制表符（Tab）
                    if '\t' in leading_spaces:
                        return False

                    # 检查行首空格个数是否为 4 的倍数
                    if len(leading_spaces) % 4 != 0:
                        return False

    return has_code_file
